    66  #define PJ_LIB__
    67  #include <time.h>
    68  #include "proj_internal.h"
    69  #include <projects.h>
    70  #include <errno.h>
    71
    72  PROJ_HEAD(unitconvert, "Unit conversion");
    73
    74  typedef double (*tconvert)(double);
    75
    76  struct TIME_UNITS {
    77      char        *id;        /* units keyword */
    78      tconvert     t_in;      /* unit -> mod. julian date funtion pointer */
    79      tconvert     t_out;     /* mod. julian date > unit function pointer */
    80      char        *name;      /* comments */
    81  };
    82
    83
    84  /***********************************************************************/
    85  static int is_leap_year(int year) {
    86  /***********************************************************************/
    87      return ((year % 4 == 0 && year % 100 != 0) || year % 400 ==0);
    88  }
    89
    90
    91  /***********************************************************************/
    92  static int days_in_year(int year) {
    93  /***********************************************************************/
    94      return is_leap_year(year) ? 366 : 365;
    95  }
    96
    97
    98  /***********************************************************************/
    99  static double mjd_to_mjd(double mjd) {
   100  /***********************************************************************
   101      Modified julian date no-op function.
   102
   103      The Julian date is defined as (fractional) days since midnight
   104      on 16th of November in 1858.
   105  ************************************************************************/
   106      return mjd;
   107  }
   108
   109
   110  /***********************************************************************/
   111  static double decimalyear_to_mjd(double decimalyear) {
   112  /***********************************************************************
   113      Epoch of modified julian date is 1858-11-16 00:00
   114  ************************************************************************/
   115      int year = (int)floor(decimalyear);
   116      double fractional_year = decimalyear - year;
   117      double mjd = (year - 1859)*365 + 14 + 31;
   118      mjd += fractional_year*days_in_year(year);
   119
   120      /* take care of leap days */
   121      year--;
   122      for (; year > 1858; year--)
   123          if (is_leap_year(year))
   124              mjd++;
   125
   126      return mjd;
   127  }
   128
   129
   130  /***********************************************************************/
   131  static double mjd_to_decimalyear(double mjd) {
   132  /***********************************************************************
   133      Epoch of modified julian date is 1858-11-16 00:00
   134  ************************************************************************/
   135      double decimalyear = mjd;
   136      double mjd_iter = 14 + 31;
   137      int year = 1859;
   138
   139      /* a smarter brain than mine could probably to do this more elegantly
   140         - I'll just brute-force my way out of this... */
   141      for (; mjd >= mjd_iter; year++) {
   142          mjd_iter += days_in_year(year);
   143      }
   144      year--;
   145      mjd_iter -= days_in_year(year);
   146
   147      decimalyear = year + (mjd-mjd_iter)/days_in_year(year);
   148      return decimalyear;
   149  }
   150
   151
   152  /***********************************************************************/
   153  static double gps_week_to_mjd(double gps_week) {
   154  /***********************************************************************
   155      GPS weeks are defined as the number of weeks since January the 6th
   156      1980.
   157
   158      Epoch of gps weeks is 1980-01-06 00:00, which in modified Julian
   159      date is 44244.
   160  ************************************************************************/
   161      return 44244.0 + gps_week*7.0;
   162  }
   163
   164
   165  /***********************************************************************/
   166  static double mjd_to_gps_week(double mjd) {
   167  /***********************************************************************
   168      GPS weeks are defined as the number of weeks since January the 6th
   169      1980.
   170
   171      Epoch of gps weeks is 1980-01-06 00:00, which in modified Julian
   172      date is 44244.
   173  ************************************************************************/
   174      return (mjd - 44244.0) / 7.0;
   175  }
   176
   177  struct TIME_UNITS time_units[] = {
   178      {"mjd",         mjd_to_mjd,         mjd_to_mjd,         "Modified julian date"},
   179      {"decimalyear", decimalyear_to_mjd, mjd_to_decimalyear, "Decimal year"},
   180      {"gps_week",    gps_week_to_mjd,    mjd_to_gps_week,    "GPS Week"},
   181      {NULL,          NULL,               NULL,               NULL}
   182  };
