   194  /***********************************************************************/
   195  static void *freeup_msg (PJ *P, int errlev) {
   196  /***********************************************************************/
   197      if (0==P)
   198          return 0;
   199
   200      if (0!=P->ctx)
   201          pj_ctx_set_errno (P->ctx, errlev);
   202
   203      pj_dealloc (P->opaque);
   204
   205      return pj_dealloc(P);
   206  }
   207
   208
   209  /***********************************************************************/
   210  static void freeup (PJ *P) {
   211  /***********************************************************************/
   212      freeup_msg (P, 0);
   213      return;
   214  }
