   216  /***********************************************************************/
   217  static XY forward_2d(LP lp, PJ *P) {
   218  /************************************************************************
   219      Forward unit conversions in the plane
   220  ************************************************************************/
   221      struct pj_opaque_unitconvert *Q = (struct pj_opaque_unitconvert *) P->opaque;
   222      PJ_TRIPLET point;
   223      point.lp = lp;
   224
   225      point.xy.x *= pj_units[Q->xy_in_id].factor / pj_units[Q->xy_out_id].factor;
   226      point.xy.y *= pj_units[Q->xy_in_id].factor / pj_units[Q->xy_out_id].factor;
   227
   228      return point.xy;
   229  }
   230
   231
   232  /***********************************************************************/
   233  static LP reverse_2d(XY xy, PJ *P) {
   234  /************************************************************************
   235      Reverse unit conversions in the plane
   236  ************************************************************************/
   237      struct pj_opaque_unitconvert *Q = (struct pj_opaque_unitconvert *) P->opaque;
   238      PJ_TRIPLET point;
   239      point.xy = xy;
   240
   241      point.xy.x *= pj_units[Q->xy_out_id].factor / pj_units[Q->xy_in_id].factor;
   242      point.xy.y *= pj_units[Q->xy_out_id].factor / pj_units[Q->xy_in_id].factor;
   243
   244      return point.lp;
   245  }
   246
   247
   248  /***********************************************************************/
   249  static XYZ forward_3d(LPZ lpz, PJ *P) {
   250  /************************************************************************
   251      Forward unit conversions the vertical component
   252  ************************************************************************/
   253      struct pj_opaque_unitconvert *Q = (struct pj_opaque_unitconvert *) P->opaque;
   254      PJ_TRIPLET point;
   255      point.lpz = lpz;
   256
   257      /* take care of the horizontal components in the 2D function */
   258      point.xy = forward_2d(point.lp, P);
   259
   260      point.xyz.z *= pj_units[Q->z_in_id].factor / pj_units[Q->z_out_id].factor;
   261
   262      return point.xyz;
   263  }
   264
   265  /***********************************************************************/
   266  static LPZ reverse_3d(XYZ xyz, PJ *P) {
   267  /************************************************************************
   268      Reverse unit conversions the vertical component
   269  ************************************************************************/
   270      struct pj_opaque_unitconvert *Q = (struct pj_opaque_unitconvert *) P->opaque;
   271      PJ_TRIPLET point;
   272      point.xyz = xyz;
   273
   274      /* take care of the horizontal components in the 2D function */
   275      point.lp = reverse_2d(point.xy, P);
   276
   277      point.xyz.z *= pj_units[Q->z_out_id].factor / pj_units[Q->z_in_id].factor;
   278
   279      return point.lpz;
   280  }
