   284  static PJ_OBS forward_obs(PJ_OBS obs, PJ *P) {
   285  /************************************************************************
   286      Forward conversion of time units
   287  ************************************************************************/
   288      struct pj_opaque_unitconvert *Q = (struct pj_opaque_unitconvert *) P->opaque;
   289      PJ_OBS out;
   290
   291      /* delegate unit conversion of physical dimensions to the 3D function */
   292      out.coo.xyz = forward_3d(obs.coo.lpz, P);
   293
   294      if (Q->t_in_id >= 0)
   295          out.coo.xyzt.t = time_units[Q->t_in_id].t_in( obs.coo.xyzt.t );
   296      if (Q->t_out_id >= 0)
   297          out.coo.xyzt.t = time_units[Q->t_out_id].t_out( out.coo.xyzt.t );
   298
   299      return out;
   300  }
