   179  static PJ_OBS pipeline_forward_obs (PJ_OBS point, PJ *P) {
   180      int i, first_step, last_step;
   181
   182      first_step = 1;
   183      last_step  = P->opaque->steps + 1;
   184
   185      for (i = first_step;  i != last_step;  i++) {
   186          proj_log_trace (P, "In[%2.2d]: %20.15g %20.15g %20.15g - %20.20s",
   187              i-first_step, point.coo.xyz.x, point.coo.xyz.y, point.coo.xyz.z,
   188              P->opaque->pipeline[i]->descr
   189          );
   190
   191          if (P->opaque->omit_forward[i])
   192              continue;
   193          if (P->opaque->reverse_step[i])
   194              point = proj_trans_obs (P->opaque->pipeline[i], PJ_INV, point);
   195          else
   196              point = proj_trans_obs (P->opaque->pipeline[i], PJ_FWD, point);
   197          if (P->opaque->depth < PIPELINE_STACK_SIZE)
   198              P->opaque->stack[P->opaque->depth++] = point;
   199      }
   200      proj_log_trace (P, "Out[ ]: %20.15g %20.15g %20.15g", point.coo.xyz.x, point.coo.xyz.y, point.coo.xyz.z);
   201
   202      P->opaque->depth = 0;    /* Clear the stack */
   203      return point;
   204  }
