   356  PJ *PROJECTION(pipeline) {
   357      int i, nsteps = 0, argc;
   358      int i_pipeline = -1, i_first_step = -1, i_current_step;
   359      char **argv, **current_argv;
   360
   361      P->fwdobs =  pipeline_forward_obs;
   362      P->invobs =  pipeline_reverse_obs;
   363      P->fwd3d  =  pipeline_forward_3d;
   364      P->inv3d  =  pipeline_reverse_3d;
   365      P->fwd    =  pipeline_forward;
   366      P->inv    =  pipeline_reverse;
   367      P->pfree  =  pipeline_freeup_wrapper;
   368
   369      P->opaque = pj_calloc (1, sizeof(struct pj_opaque));
   370      if (0==P->opaque)
   371          return 0;
   372
   373      argc = (int)argc_params (P->params);
   374      P->opaque->argv = argv = argv_params (P->params, argc);
   375      if (0==argv)
   376          return pipeline_freeup (P, ENOMEM);
   377
   378      P->opaque->current_argv = current_argv = pj_calloc (argc, sizeof (char *));
   379      if (0==current_argv)
   380          return pipeline_freeup (P, ENOMEM);
   381
   382      /* Do some syntactical sanity checking */
   383      for (i = 0;  i < argc;  i++) {
   384          if (0==strcmp ("step", argv[i])) {
   385              if (-1==i_pipeline) {
   386                  proj_log_error (P, "Pipeline: +step before +proj=pipeline");
   387                  return pipeline_freeup (P, -50);
   388              }
   389              if (0==nsteps)
   390                  i_first_step = i;
   391              nsteps++;
   392              continue;
   393          }
   394
   395          if (0==strcmp ("proj=pipeline", argv[i])) {
   396              if (-1 != i_pipeline) {
   397                  proj_log_error (P, "Pipeline: Nesting invalid");
   398                  return pipeline_freeup (P, -50); /* ERROR: nested pipelines */
   399              }
   400              i_pipeline = i;
   401          }
   402      }
   403      nsteps--; /* Last instance of +step is just a sentinel */
   404      P->opaque->steps = nsteps;
   405
   406      if (-1==i_pipeline)
   407          return pipeline_freeup (P, -50); /* ERROR: no pipeline def */
   408
   409      if (0==nsteps)
   410          return pipeline_freeup (P, -50); /* ERROR: no pipeline def */
   411
   412      /* Make room for the pipeline and execution indicators */
   413      if (0==pj_create_pipeline (P, nsteps))
   414          return pipeline_freeup (P, ENOMEM);
   415
   416      /* Now loop over all steps, building a new set of arguments for each init */
   417      for (i_current_step = i_first_step, i = 0;  i < nsteps;  i++) {
   418          int j;
   419          int  current_argc = 0;
   420          PJ     *next_step = 0;
   421
   422          /* Build a set of setup args for the current step */
   423          proj_log_trace (P, "Pipeline: Building arg list for step no. %d", i);
   424
   425          /* First add the step specific args */
   426          for (j = i_current_step + 1;  0 != strcmp ("step", argv[j]); j++)
   427              current_argv[current_argc++] = argv[j];
   428
   429          i_current_step = j;
   430
   431          /* Then add the global args */
   432          for (j = i_pipeline + 1;  0 != strcmp ("step", argv[j]); j++)
   433              current_argv[current_argc++] = argv[j];
   434
   435          /* Finally handle non-symmetric steps and inverted steps */
   436          for (j = 0;  j < current_argc; j++) {
   437              if (0==strcmp("omit_inv", current_argv[j])) {
   438                  P->opaque->omit_inverse[i+1] = 1;
   439                  P->opaque->omit_forward[i+1] = 0;
   440              }
   441              if (0==strcmp("omit_fwd", current_argv[j])) {
   442                  P->opaque->omit_inverse[i+1] = 0;
   443                  P->opaque->omit_forward[i+1] = 1;
   444              }
   445              if (0==strcmp("inv", current_argv[j]))
   446                  P->opaque->reverse_step[i+1] = 1;
   447          }
   448
   449          proj_log_trace (P, "Pipeline: init - %s, %d", current_argv[0], current_argc);
   450          for (j = 1;  j < current_argc; j++)
   451              proj_log_trace (P, "    %s", current_argv[j]);
   452
   453          next_step = pj_init (current_argc, current_argv);
   454          proj_log_trace (P, "Pipeline: Step %d at %p", i, next_step);
   455          if (0==next_step) {
   456              proj_log_error (P, "Pipeline: Bad step definition: %s", current_argv[0]);
   457              return pipeline_freeup (P, -50); /* ERROR: bad pipeline def */
   458          }
   459          P->opaque->pipeline[i+1] = next_step;
   460          proj_log_trace (P, "Pipeline:    step done");
   461      }
   462
   463      proj_log_trace (P, "Pipeline: %d steps built. Determining i/o characteristics", nsteps);
   464
   465      /* Determine forward input (= reverse output) data type */
   466
   467      /* First locate the first forward-active pipeline step */
   468      for (i = 0;  i < nsteps;  i++)
   469          if (0==P->opaque->omit_forward[i+1])
   470              break;
   471      if (i==nsteps) {
   472          proj_log_error (P, "Pipeline: No forward steps");
   473          return pipeline_freeup (P, -50);
   474      }
   475
   476      if (P->opaque->reverse_step[i + 1])
   477          P->left = P->opaque->pipeline[i + 1]->right;
   478      else
   479          P->left = P->opaque->pipeline[i + 1]->left;
   480
   481      if (P->left==PJ_IO_UNITS_CLASSIC) {
   482          if (P->opaque->reverse_step[i + 1])
   483              P->left = PJ_IO_UNITS_METERS;
   484          else
   485              P->left = PJ_IO_UNITS_RADIANS;
   486      }
   487
   488      /* Now, correspondingly determine forward output (= reverse input) data type */
   489
   490      /* First locate the last reverse-active pipeline step */
   491      for (i = nsteps - 1;  i >= 0;  i--)
   492          if (0==P->opaque->omit_inverse[i+1])
   493              break;
   494      if (i==-1) {
   495          proj_log_error (P, "Pipeline: No reverse steps");
   496          return pipeline_freeup (P, -50);
   497      }
   498
   499      if (P->opaque->reverse_step[i + 1])
   500          P->right = P->opaque->pipeline[i + 1]->left;
   501      else
   502          P->right = P->opaque->pipeline[i + 1]->right;
   503
   504      if (P->right==PJ_IO_UNITS_CLASSIC) {
   505          if (P->opaque->reverse_step[i + 1])
   506              P->right = PJ_IO_UNITS_RADIANS;
   507          else
   508              P->right = PJ_IO_UNITS_METERS;
   509      }
   510      proj_log_trace (P, "Pipeline: Units - left: [%s], right: [%s]\n",
   511          P->left ==PJ_IO_UNITS_RADIANS? "angular": "linear",
   512          P->right==PJ_IO_UNITS_RADIANS? "angular": "linear");
   513
   514      return P;
   515  }
